#include "courses.hpp"

using namespace std;

Course::Course(int i, string cn, int c, string pi, string pn, string t, string ed, int cu, int p, vector<int>mi)
{
    id = i;
    name = cn;
    capacity = c;
    professor_id = pi;
    professor_name = pn;
    time = t;
    exam_date = ed;
    class_number = cu;
    prerequisite = p;
    major_ids = mi;
}

void Course::view_all_lessons()
{
    cout << id << " " << name << " " << capacity << " " << professor_name << endl;
}

void Course::view_the_specific_lesson()
{
    cout << id << " " << name << " " << capacity << " " << professor_name << " " << time << " " << exam_date << " " << class_number << endl;
}

string Course::create_course_inf()
{
    string course_info;
    course_info = to_string(id) + " " + name + " " + to_string(capacity) + " " + professor_name + " " + time + " " + exam_date + " " + to_string(class_number);
    return course_info;
}

void Course::add_TA(string student_id)
{
    if (find(connected_users.begin(), connected_users.end(), user_id) == connected_users.end())
        TAs.push_back(student_id);
}

void Course::add_post_in_channel(string entered_id, string user_name, string title, string message, string image_address)
{
    bool can_postint = false;
    if (entered_id == professor_id)
        can_postint = true;
    for (auto TA : TAs) {
        if (TA == entered_id)
            can_postint = true;
    }
    if (!can_postint)
        throw runtime_error(ILLEGAL_ACCESS_MESSAGE);

    post_id += 1;
    int id = post_id;
    Channel_Post* new_post = new Channel_Post{id, user_name, title, message, image_address};
    channel.push_back(new_post);
}
